import streamlit as st # Set page configuration st.set_page_config(page_title="Decimal to Binary Converter", layout="centered") # Add styling st.title("Decimal & Binary Converter") # Function to convert decimal to binary def decimal_to_binary(n): try: return bin(int(n))[2:] except ValueError: return None # Function to convert binary to decimal def binary_to_decimal(b): try: return int(b, 2) except ValueError: return None # User interface st.subheader("Decimal to Binary") decimal_input = st.number_input( "Enter a decimal number", value=0.0, step=1.0) convert_btn = st.button("Convert to Binary") if convert_btn: binary_result = decimal_to_binary(str(int(decimal_input))) if binary_result: st.success(f"Binary: {binary_result}") else: st.error("Please enter a valid decimal number.") st.subheader("Binary to Decimal") binary_input = st.text_input( "Enter a binary number") convert_deci_btn = st.button("Convert to Decimal") if convert_deci_btn: decimal_result = binary_to_decimal(binary_input) if decimal_result is not None: st.success(f"Decimal: {decimal_result}") else: st.error("Please enter valid binary input.") Save this as a python file and run it using streamlit run app.py.